<template><section class="module-page module-composed-page course-admin-page"><header class="module-heading"><div><h1>课程管理</h1><p>创建课程、维护课程资源并控制发布状态。</p></div><el-button type="primary" icon="el-icon-plus" @click="openCourse()">新建课程</el-button></header><section class="course-summary"><div><small>课程目录</small><strong>{{ courses.length }}</strong><span>已创建课程</span></div><div><small>资源总数</small><strong>{{ resourceCount }}</strong><span>电子书、视频、PPT 和压缩包</span></div><div><small>已发布</small><strong>{{ publishedCount }}</strong><span>普通用户可见课程</span></div></section><div v-if="courses.length" class="admin-course-grid"><article v-for="item in courses" :key="item.course.courseId" class="admin-course-card"><header><div class="course-mark"><i class="el-icon-reading" /></div><div class="course-card-title"><h2>{{ item.course.name }}</h2><span>{{ item.course.courseType }}</span></div><el-tag size="small" :type="item.course.enabled?'success':'info'">{{ item.course.enabled?'已发布':'草稿' }}</el-tag></header><p>{{ item.course.description || '暂无课程简介' }}</p><div class="admin-resource-list"><span v-for="resource in item.resources" :key="resource.resourceId"><i :class="resourceIcon(resource.resourceType)" />{{ resource.name }}</span><em v-if="!item.resources.length">暂无课程资源</em></div><footer><el-button size="small" @click="openCourse(item.course)">编辑课程</el-button><el-button size="small" @click="openResource(item.course)">添加资源</el-button><el-button size="small" :type="item.course.enabled?'warning':'success'" @click="toggle(item.course)">{{ item.course.enabled?'停用':'发布' }}</el-button></footer></article></div><div v-else class="course-empty"><i class="el-icon-reading" /><strong>暂无课程</strong><span>点击右上角新建课程，开始维护课程内容。</span></div><el-dialog :title="editing ? '编辑课程' : '新建课程'" :visible.sync="courseDialog" width="500px"><el-form :model="form" label-width="90px"><el-form-item label="课程名称"><el-input v-model="form.name" /></el-form-item><el-form-item label="课程类别"><el-input v-model="form.courseType" /></el-form-item><el-form-item label="课程简介"><el-input v-model="form.description" type="textarea" :rows="3" /></el-form-item></el-form><span slot="footer"><el-button @click="courseDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveCourse">保存</el-button></span></el-dialog><el-dialog title="添加课程资源" :visible.sync="resourceDialog" width="520px"><el-form :model="resource" label-width="90px"><el-form-item label="资源文件"><el-upload action="#" :auto-upload="false" :show-file-list="false" :on-change="uploadResource"><el-button icon="el-icon-upload2">选择文件并上传</el-button></el-upload></el-form-item><el-form-item label="资源类型"><el-select v-model="resource.resourceType" style="width:100%"><el-option v-for="item in resourceTypes" :key="item" :label="item" :value="item" /></el-select></el-form-item><el-form-item label="资源名称"><el-input v-model="resource.name" /></el-form-item><el-form-item label="SHA-256"><el-input v-model="resource.sha256" /></el-form-item></el-form><span slot="footer"><el-button @click="resourceDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveResource">添加</el-button></span></el-dialog></section></template>
<script>
import { listAdminCourses, createCourse, updateCourse, setCourseEnabled, addCourseResource, uploadCourseResource } from '@/api/Courses'
export default { data: () => ({ loading:false, saving:false, uploading:false, courses:[], courseDialog:false, resourceDialog:false, editing:false, selectedCourse:null, form:{ name:'', courseType:'', description:'' }, resource:{ resourceType:'EBOOK', name:'', storageKey:'', contentLength:null, mimeType:'', sha256:'' }, resourceTypes:['EBOOK','VIDEO','PPT','ARCHIVE'] }), computed:{resourceCount(){return this.courses.reduce((sum,item)=>sum+(item.resources||[]).length,0)},publishedCount(){return this.courses.filter(item=>item.course.enabled).length}}, created(){this.load()}, methods:{async load(){this.loading=true;try{const r=await listAdminCourses();this.courses=r.data||[]}finally{this.loading=false}},openCourse(c){this.editing=!!c;this.form=c?Object.assign({},c):{name:'',courseType:'',description:''};this.courseDialog=true},async saveCourse(){this.saving=true;try{await(this.editing?updateCourse(this.form.courseId,this.form):createCourse(this.form));this.courseDialog=false;await this.load()}finally{this.saving=false}},async toggle(c){await setCourseEnabled(c.courseId,!c.enabled);await this.load()},openResource(c){this.selectedCourse=c;this.resource={resourceType:'EBOOK',name:'',storageKey:'',contentLength:null,mimeType:'',sha256:''};this.resourceDialog=true},resourceIcon(t){return({EBOOK:'el-icon-document',VIDEO:'el-icon-video-play',PPT:'el-icon-data-board',ARCHIVE:'el-icon-folder'})[t]||'el-icon-document'},async uploadResource(file){this.uploading=true;try{const r=await uploadCourseResource(file.raw);this.resource=Object.assign(this.resource,r.data||{});this.$message.success('文件上传完成')}finally{this.uploading=false}},async saveResource(){if(!this.resource.storageKey){this.$message.error('请先上传资源文件');return}this.saving=true;try{await addCourseResource(this.selectedCourse.courseId,this.resource);this.resourceDialog=false;await this.load()}finally{this.saving=false}}}}
</script>
<style scoped>.course-admin-page{width:100%}.course-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;margin-bottom:18px;background:var(--ui-border);border:1px solid var(--ui-border)}.course-summary>div{padding:16px 18px;background:var(--ui-surface)}.course-summary small,.course-summary span{display:block;color:var(--ui-muted);font-size:12px}.course-summary strong{display:block;margin:6px 0;font-size:26px;color:var(--ui-text)}.admin-course-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.admin-course-card{padding:18px;background:var(--ui-surface);border:1px solid var(--ui-border);border-radius:10px;box-shadow:var(--ui-shadow)}.admin-course-card header{display:flex;align-items:flex-start;gap:10px}.course-mark{display:grid;place-items:center;width:38px;height:38px;color:var(--ui-primary);background:var(--ui-primary-soft);border-radius:50%}.course-card-title{min-width:0;flex:1}.course-card-title h2{margin:0;overflow:hidden;font-size:17px;text-overflow:ellipsis;white-space:nowrap}.course-card-title span{display:block;margin-top:4px;color:var(--ui-muted);font-size:12px}.admin-course-card>p{min-height:42px;margin:16px 0;color:var(--ui-muted);font-size:13px;line-height:1.6}.admin-resource-list{display:grid;gap:6px;min-height:62px}.admin-resource-list span,.admin-resource-list em{overflow:hidden;color:var(--ui-text);font-size:12px;text-overflow:ellipsis;white-space:nowrap}.admin-resource-list i{margin-right:6px;color:var(--ui-primary)}.admin-resource-list em{color:var(--ui-muted);font-style:normal}.admin-course-card footer{display:flex;gap:8px;margin-top:16px;padding-top:14px;border-top:1px solid var(--ui-border)}.course-empty{display:grid;place-items:center;gap:8px;min-height:260px;color:var(--ui-muted);background:var(--ui-surface);border:1px solid var(--ui-border);border-radius:10px}.course-empty i{font-size:44px;color:var(--ui-primary)}.course-empty strong{color:var(--ui-text);font-size:18px}.course-empty span{font-size:13px}@media(max-width:950px){.admin-course-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:620px){.course-summary{grid-template-columns:1fr}.admin-course-grid{grid-template-columns:1fr}.admin-course-card footer{flex-wrap:wrap}}
</style>
